import { AuditActorType, AuditLogRequest, AuditOutcome } from "./common"

/**
 * An audit log to record. The ID is always generated by the Audit Module.
 */
export interface CreateAuditLogDTO {
  /**
   * The name of the action, such as `order.cancel`.
   */
  action: string

  /**
   * The type of actor that performed the action.
   *
   * @defaultValue "system"
   */
  actor_type?: AuditActorType

  /**
   * The ID of the user, API key, or customer that performed the action.
   */
  actor_id?: string | null

  /**
   * The ID of the Medusa staff member acting as the actor, on Medusa Cloud.
   */
  impersonator_id?: string | null

  /**
   * The type of resource acted on, such as `order`.
   */
  resource_type?: string | null

  /**
   * The ID of the resource acted on.
   */
  resource_id?: string | null

  /**
   * How the action ended.
   *
   * @defaultValue "succeeded"
   */
  outcome?: AuditOutcome

  /**
   * When the action started, as a `Date` or an ISO 8601 string.
   *
   * @defaultValue The time `createAuditLogs` is called.
   */
  started_at?: Date | string

  /**
   * When the action ended, as a `Date` or an ISO 8601 string.
   *
   * @defaultValue The value of `started_at`.
   */
  ended_at?: Date | string

  /**
   * The HTTP details. Leave empty for an audit log written outside an API request.
   */
  request?: AuditLogRequest | null

  /**
   * The request fields to keep. Never pass a whole request body.
   */
  request_data?: Record<string, unknown> | null

  /**
   * The response fields to keep. Never pass a whole response body.
   */
  response_data?: Record<string, unknown> | null

  /**
   * Any other data to attach to the audit log.
   */
  metadata?: Record<string, unknown> | null
}
